source "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"

_choice_dbname() {
    _argc_util_cache 300 _choice_dbname_uncached "pg_dump_dbname:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_dbname_uncached() {
    _helper_psql_query 'select datname from pg_database where datallowconn order by 1'
}

_choice_extension() {
    _argc_util_cache 300 _choice_extension_uncached "pg_dump_extension:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_extension_uncached() {
    _helper_psql_query 'select name from pg_available_extensions order by 1' "${argc_dbname:-postgres}"
}

_choice_role() {
    _argc_util_cache 300 _choice_role_uncached "pg_dump_role:${argc_dbname:-}:${argc_host:-}:${argc_port:-}"
}

_choice_role_uncached() {
    _helper_psql_query 'select rolname from pg_roles order by 1' "${argc_dbname:-postgres}" 0
}

_choice_schema() {
    _argc_util_cache 300 _choice_schema_uncached "pg_dump_schema:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_schema_uncached() {
    _helper_psql_query "select nspname from pg_namespace where nspname not in ('pg_catalog','information_schema') and nspname not like 'pg\_%' order by 1" "${argc_dbname:-postgres}"
}

_choice_table() {
    _argc_util_cache 300 _choice_table_uncached "pg_dump_table:${argc_dbname:-}:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_table_uncached() {
    _helper_psql_query "select n.nspname || '.' || c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace where c.relkind in ('r','p','v','m','f') and n.nspname not in ('pg_catalog','information_schema') and n.nspname not like 'pg\_%' order by 1 limit 500" "${argc_dbname:-postgres}"
}

_choice_username() {
    _argc_util_cache 300 _choice_username_uncached "pg_dump_username:${argc_dbname:-}:${argc_host:-}:${argc_port:-}"
}

_choice_username_uncached() {
    _helper_psql_query 'select rolname from pg_roles where rolcanlogin order by 1' "${argc_dbname:-postgres}" 0
}

_helper_psql_query() {
    local sql="$1" dbname="${2:-postgres}" with_user="${3:-1}"
    command -v psql >/dev/null 2>&1 || return 0
    local args=(-X -w -A -t -d "$dbname")
    [[ -n "${argc_host:-}" ]] && args+=(-h "$argc_host")
    [[ -n "${argc_port:-}" ]] && args+=(-p "$argc_port")
    if [[ "$with_user" == 1 && -n "${argc_username:-}" ]]; then
        args+=(-U "$argc_username")
    fi
    PGCONNECT_TIMEOUT=1 psql "${args[@]}" -c "$sql" 2>/dev/null
}
